#!/usr/bin/env python
# This script creates evaluation plots for prediction files generated by the
# predict.py script
#
# Steven Lu
# December 2, 2024

import os
import sys
import rasterio
import numpy as np
import pandas as pd
from scipy import stats
from tqdm import tqdm
import matplotlib.pyplot as plt
from sklearn.metrics import mean_squared_error


def _resolve_parquet(parquet_file, prefer='test'):
    """Accept either a predictions parquet or the run's output directory.

    pandas treats a directory as a PARTITIONED parquet dataset and tries to read
    every file in it, so passing an output dir fails on the first .png with
    "Parquet magic bytes not found". Resolve a directory to the parquet inside it
    instead, preferring the test split.
    """
    if not os.path.isdir(parquet_file):
        return parquet_file

    candidates = sorted(f for f in os.listdir(parquet_file)
                        if f.startswith('predictions_') and f.endswith('.parquet'))
    if not candidates:
        sys.exit(f"No predictions_*.parquet in {parquet_file}")
    chosen = next((f for f in candidates if f == f'predictions_{prefer}.parquet'),
                  candidates[0])
    if len(candidates) > 1:
        print(f"{parquet_file} contains {len(candidates)} parquet(s): "
              f"{', '.join(candidates)}")
    print(f"Using {chosen}")
    return os.path.join(parquet_file, chosen)


def _load_from_parquet(parquet_file, eval_min_height, eval_max_height):
    """Load pred_arr and gedi_arr from a parquet file (y_true/y_pred already in metres)."""
    df = pd.read_parquet(_resolve_parquet(parquet_file))
    gedi_arr = df['y_true'].values.astype(np.float64)
    pred_arr = df['y_pred'].values.astype(np.float64)

    if eval_min_height is not None:
        mask = gedi_arr >= eval_min_height
        gedi_arr = gedi_arr[mask]
        pred_arr = pred_arr[mask]

    if eval_max_height is not None:
        mask = gedi_arr <= eval_max_height
        gedi_arr = gedi_arr[mask]
        pred_arr = pred_arr[mask]

    return pred_arr, gedi_arr


def main(preds_dir, gedi_dir, data_file, out_plot, subsample_factor, ignore_above,
         eval_min_height, eval_max_height, parquet=None):
    if parquet is not None:
        if not os.path.exists(parquet):
            print(f'Parquet file not found: {parquet}')
            sys.exit(1)
        pred_arr, gedi_arr = _load_from_parquet(parquet, eval_min_height, eval_max_height)
    else:
        for f in [preds_dir, gedi_dir, data_file]:
            if not os.path.exists(f):
                print(f'Input dir/file not found: {f}')
                sys.exit(1)

        with open(data_file, 'r') as f:
            tile_indices = f.readlines()
            tile_indices = [t.strip() for t in tile_indices]

        # Load in all prediction and GEDI tiles
        pred_arr = np.array([])
        gedi_arr = np.array([])
        for tile_index in tqdm(tile_indices, desc='Loading tiles'):
            pred_file = os.path.join(preds_dir,
                                     f'prediction_rh98_30.0m_{tile_index.replace("_v6", "")}.tif')
            pred_src = rasterio.open(pred_file, 'r')
            pred_data = np.squeeze(pred_src.read(), axis=0)
            pred_src.close()

            gedi_file = os.path.join(gedi_dir,
                                     f'gedi_rh98_30.0m_{tile_index.replace("_v6", "")}.tif')
            gedi_src = rasterio.open(gedi_file, 'r')
            gedi_data = np.squeeze(gedi_src.read(), axis=0)
            gedi_src.close()

            # Mask out locations where GEDI ground truth isn't available
            mask = np.where(gedi_data != 0)
            pred_data = pred_data[mask]
            gedi_data = gedi_data[mask]

            # Mask out locations where GEDI ground truth values are smaller than
            # eval_min_height or greater than eval_max_height
            if eval_min_height is not None:
                min_mask = np.where(gedi_data / 100. >= eval_min_height)
                gedi_data = gedi_data[min_mask]
                pred_data = pred_data[min_mask]

            if eval_max_height is not None:
                max_mask = np.where(gedi_data / 100. <= eval_max_height)
                gedi_data = gedi_data[max_mask]
                pred_data = pred_data[max_mask]

            pred_arr = np.hstack((pred_arr, pred_data.flatten()))
            gedi_arr = np.hstack((gedi_arr, gedi_data.flatten()))

        # Predictions are already in m, but GEDI values are in cm. Convert GEDI values
        # to m.
        gedi_arr = gedi_arr / 100.

    # Generate evaluation figure
    fig, _ = plt.subplots()

    if ignore_above <= 0:
        maxx = np.max(gedi_arr)
        minx = np.min(gedi_arr)
        maxy = np.max(pred_arr)
        miny = np.min(pred_arr)
        max_value = np.max([maxx, maxy])
        min_value = np.min([minx, miny])
    else:
        max_value = ignore_above
        min_value = 0

        mask = gedi_arr <= ignore_above
        pred_arr = pred_arr[mask]
        gedi_arr = gedi_arr[mask]

    # Plot perfect prediction line for reference
    plt.plot((min_value, max_value), (min_value, max_value), '--', color='gray',
             linewidth=1)

    # Compute Pearson correlation coefficient r and RMSE
    r, _ = stats.pearsonr(gedi_arr, pred_arr)
    mse = mean_squared_error(gedi_arr, pred_arr)
    rmse = np.sqrt(mse)

    if len(gedi_arr) > 10000:
        gedi_arr = gedi_arr[::subsample_factor]
        pred_arr = pred_arr[::subsample_factor]

    # Scatter plot of predictions v.s. labels
    xy = np.vstack([gedi_arr, pred_arr])
    z = stats.gaussian_kde(xy)(xy)
    idx = z.argsort()
    d_true_arr = gedi_arr[idx]
    d_pred_arr = pred_arr[idx]
    z = z[idx]

    plt.scatter(d_true_arr, d_pred_arr, c=z, cmap='jet',
                label='RMSE = %.3f\nPearson correlation = %.3f' % (rmse, r),
                s=0.5)
    cbar = plt.colorbar()
    cbar.set_ticks([])

    # Plot linear regression line for the predictions
    coef = np.polyfit(gedi_arr, pred_arr, 1)
    poly1d = np.poly1d(coef)
    plt.plot(gedi_arr, poly1d(gedi_arr), '--', color='black', linewidth=1,
             label=f'Regression line (slope={coef[0]:.2f})')

    # Plot the mean and std of the predictions based on the bins defined by the
    # labels
    bins = np.linspace(min_value, max_value,
                       int(np.ceil((max_value - min_value) / 1)))
    digitized = np.digitize(gedi_arr, bins)
    x_means = np.array([gedi_arr[digitized == i].mean() for i in range(1, len(bins))])
    y_means = np.array([pred_arr[digitized == i].mean() for i in range(1, len(bins))])
    y_stds = np.array([pred_arr[digitized == i].std() for i in range(1, len(bins))])
    plt.plot(x_means, y_means, '--', color='mediumvioletred', linewidth=1,
             label='Binned prediction mean and std')
    plt.fill_between(x_means, y_means - y_stds, y_means + y_stds, alpha=0.3,
                     edgecolor='deeppink', facecolor='hotpink')

    plt.xlabel('Ground Truth GEDI rh98 (unit: m)')
    plt.ylabel('Predicted GEDI rh98 (unit: m)')
    plt.xlim((min_value, max_value))
    plt.ylim((min_value, max_value))
    plt.legend(loc='upper right')
    plt.savefig(out_plot)
    plt.close()


if __name__ == '__main__':
    import argparse

    parser = argparse.ArgumentParser()
    parser.add_argument('preds_dir', type=str, nargs='?', default=None)
    parser.add_argument('gedi_dir', type=str, nargs='?', default=None)
    parser.add_argument('data_file', type=str, nargs='?', default=None)
    parser.add_argument('out_plot', type=str, nargs='?', default=None)
    parser.add_argument('--subsample_factor', type=int, default=10)
    parser.add_argument('--ignore_above', type=float, default=70,
                        help='If labels are above the number defined by '
                             '--ignore_above, they will not be included in the '
                             'evaluation. Default is 70 meters. If set to 0 '
                             'meter, all samples will be included in evaluation.')
    parser.add_argument('--eval_min_height', type=float, required=False)
    parser.add_argument('--eval_max_height', type=float, required=False)
    parser.add_argument('--parquet', type=str, default=None,
                        help='Path to a predictions parquet file (y_true, y_pred columns, '
                             'values in metres). When set, preds_dir/gedi_dir/data_file '
                             'are not required.')

    args = parser.parse_args()

    if args.parquet is None and any(v is None for v in [args.preds_dir, args.gedi_dir, args.data_file]):
        parser.error('preds_dir, gedi_dir, and data_file are required unless --parquet is provided')

    if args.parquet is not None:
        # Resolve here (not lazily inside the loader) so the default figure path is
        # derived from the actual parquet -- otherwise passing a run DIRECTORY puts
        # the plot next to the directory instead of inside it.
        args.parquet = _resolve_parquet(args.parquet)

    if args.out_plot is None:
        if args.parquet is not None:
            p = os.path.splitext(args.parquet)
            args.out_plot = p[0] + '_evaluate.png'
        else:
            parser.error('out_plot is required when not using --parquet')

    main(**vars(args))